// Shuffle function
function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// CERTIFICATE-SPECIFIC banks — CP exams draw only from CP bank, SCP exams only from SCP bank (no mixing)
const BANKS = { "SHRM-CP": QUESTION_BANK, "SHRM-SCP": SCP_BANK };

// Generate a certificate-specific exam (shuffled differently per exam number)
export function getExamQuestions(examNumber, certificateType = "SHRM-CP") {
  const bank = BANKS[certificateType] || QUESTION_BANK;
  const shuffled = shuffleArray(bank);
  return shuffled.slice(0, Math.min(QUESTIONS_PER_EXAM, shuffled.length));
}

// عرض المحاكاة الكامل المعروض على الطالب عبر المنصة:
// 10 امتحانات × 134 سؤالاً × شهادتين (CP و SCP) = 2680 سؤالاً معروضاً
export const QUESTIONS_PER_EXAM = 134;
export const EXAMS_PER_CERT = 10;
export const EXAM_CERTS = ["SHRM-CP", "SHRM-SCP"];
export const TOTAL_EXAM_QUESTIONS = QUESTIONS_PER_EXAM * EXAMS_PER_CERT * EXAM_CERTS.length; // 2680

// حجم بنك الأسئلة المدمج لكل شهادة (عدد الأسئلة الفريدة المتاحة للسحب منها عبر الامتحانات)
export function getBankSize(certificateType = "SHRM-CP") {
  return (BANKS[certificateType] || QUESTION_BANK).length;
}
// إجمالي أسئلة المحاكاة المعروضة لدورة ما = عدد الامتحانات × حجم البنك (1340 لكل دورة)
export function getExamOfferingForCert(certificateType = "SHRM-CP") {
  return getBankSize(certificateType) * EXAMS_PER_CERT;
}

export default QUESTION_BANK;